"""Local source-bound prompt preparation. No segmentation/model/network download."""
from pathlib import Path
import hashlib,io,json,uuid
from PIL import Image,UnidentifiedImageError


def prepare_source(data:bytes,out_root:Path):
    if not data or len(data)>25_000_000:raise ValueError('source must be 1 byte to 25 MB')
    try:
        with Image.open(io.BytesIO(data)) as im:
            if im.width*im.height>4_000_000:raise ValueError('source exceeds 4 million pixels; no silent resize')
            if min(im.size)<3:raise ValueError('source too small')
            # Match the CLI decode exactly, without browser EXIF rotation.
            rgb=im.convert('RGB');size=list(im.size)
    except (UnidentifiedImageError,OSError) as e:raise ValueError('source is not a supported image') from e
    key='prompt-'+uuid.uuid4().hex[:12];root=out_root/key;root.mkdir(parents=True)
    (root/'original-source.bin').write_bytes(data);rgb.save(root/'source-preview.png')
    d=dict(source_sha256=hashlib.sha256(data).hexdigest(),image_size=size,preview_url='/file/'+key+'/source-preview.png',
           job=key,decode='PIL RGB, no EXIF transpose; same coordinates as prompted-mask CLI')
    (root/'source-manifest.json').write_text(json.dumps(d,indent=2));return d


PAGE=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Renderello mask prompts</title>
<style>*{box-sizing:border-box}body{font-family:system-ui,sans-serif;max-width:1100px;margin:24px auto;padding:0 16px;color:#1c1c1e}h1{font-size:28px}p{line-height:1.5}.note{padding:12px;background:#f2f2f4;border-radius:8px}label{display:block;margin:12px 0 4px;font-weight:600}input,select,button{font:inherit;max-width:100%}input[type=text],select{width:100%;padding:10px}button,a.download{padding:10px 14px;border-radius:6px;border:1px solid #777;background:white;color:#1c1c1e;min-height:44px;cursor:pointer}button:disabled{opacity:.5;cursor:default}.controls{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:12px 0}.controls>*{flex:0 1 auto}.panel{border:1px solid #ccc;padding:16px;border-radius:8px;margin:18px 0}#viewport{overflow:auto;max-height:650px;width:100%;border:1px solid #aaa}canvas{display:block;width:100%;max-width:none;height:auto;border:1px solid #aaa;touch-action:none;background:#eee}#status{overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f2f2f4;padding:12px}#objects{width:100%}a{color:#0756b8}a.download{display:inline-block}#reviewed{width:20px;height:20px;vertical-align:middle}@media(max-width:500px){body{margin:16px auto}h1{font-size:24px}.panel{padding:10px}button{flex-grow:1}}</style></head><body>
<a href="/">Back to Renderello</a><h1>Review mask prompts</h1>
<p class="note">Preparation only. Draw boxes around each object, then add positive points on the product and negative points in empty holes or background. Drawing and export are preparation only. The separate explicit CPU button below can run the reviewed pipeline when configured; neither route certifies a correct mask.</p>
<label for="source">Original source photo</label><input id="source" type="file" accept="image/*"><div class="controls"><button id="prepare">Load source for review</button></div>
<p>Photo bytes stay in this local Renderello server's output folder. The preview uses the same decoded pixels as the CLI, without browser EXIF rotation. Do not edit or recompress the original after exporting prompts.</p>
<p id="status" role="status" aria-live="polite">Choose an image. Maximum 4 million pixels / 25 MB.</p>
<div class="panel"><label for="objects">Selected object</label><select id="objects" disabled></select><label for="name">Object name</label><input id="name" type="text" maxlength="80" disabled><div class="controls"><button id="add" disabled>Add another object</button><button id="remove" disabled>Remove selected object</button><button id="undo" disabled>Undo last edit</button></div>
<label for="mode">Drawing mode</label><select id="mode" disabled><option value="pan">Pan</option><option value="box" selected>Draw box</option><option value="positive">Positive point</option><option value="negative">Negative point</option></select>
<p>Blue boxes and numbered labels identify selected objects. Green points keep product; red points exclude background. Up to 8 objects and 32 points per object. The combined mask includes only objects you explicitly select.</p><p id="modehint">Box: drag around the whole object.</p><label for="zoom">Image zoom</label><select id="zoom"><option value="100">Fit width</option><option value="200">2x</option><option value="400">4x</option></select><p>For small details, zoom in and choose Pan to move around the image. Return to Draw box or a point mode to annotate. Desktop review is recommended for precise edges. Mobile layout and pointer coordinates were tested; real touch annotation is not verified.</p><div id="viewport"><canvas id="canvas" width="600" height="300" aria-label="Source image annotation canvas"></canvas></div><p id="geometry">No source loaded.</p>
</div><label><input id="reviewed" type="checkbox" disabled> I inspected these boxes and points against this source image.</label>
<div class="controls"><button id="export" disabled>Export reviewed prompt JSON</button></div><p id="download"></p><pre id="json" hidden></pre>
<h2>Run reviewed intent + automatic alpha</h2><p>Step 1 runs CPU HQ-SAM only. Inspect its actual silhouette on all three backgrounds. Step 2 requires your explicit acceptance of that exact preview before intersecting it with the automatic alpha. A reviewed box is not a reviewed silhouette. Add at least one positive point on each product. If the mask has holes, selects background or loses product, change the prompts and retry instead of accepting. It does not run BiRefNet, download weights or certify quality. Intersection cannot recover automatic-mask missing parts. Inspect all three result backgrounds. Manual review stays required.</p><p id="runconfig">Checking server checkpoint setup...</p><label for="automatic">Existing automatic result ZIP (flat files)</label><input id="automatic" type="file" accept=".zip"><p>ZIP must contain source.png, cutout.png, estimated-alpha.png and its original bilateral/pyramid/semantic mask manifest, all at ZIP root.20MBcompressed/40MBunpacked cap. Must match the exact source.</p><div class="controls"><button id="runmask" disabled>1. Preview inferred silhouette (CPU)</button></div><p id="runstatus" role="status" aria-live="polite">Export reviewed prompts first.</p><div id="maskresults"></div><label><input id="silhouette" type="checkbox" disabled> I inspected this exact inferred silhouette on white, black and magenta. It keeps the selected product without unwanted holes or background.</label><div class="controls"><button id="combine" disabled>2. Accept silhouette and combine alpha</button></div><div id="combinedresults"></div><h2>Or run the optional mask stage by CLI</h2><p>This page does not install packages or download weights. Use the exact original photo and the reviewed JSON with the pinned checkpoint:</p><pre>python -m renderello.cli prompted-mask --source ORIGINAL_PHOTO --prompts reviewed-prompts.json --checkpoint sam_hq_vit_tiny.pth --out NEW_ATTEMPT</pre><p>Then inspect all black/white/magenta mask previews. Scores do not verify holes or completeness. Cropped parts cannot be recovered; source background colors may remain on edges. Owner-PC model execution is not verified by this editor.</p>
<script>
'use strict';
const $=id=>document.getElementById(id),c=$('canvas'),ctx=c.getContext('2d');
let state=null,img=null,selected=0,drag=null,history=[],generation=0,url=null,pan=null,job=null,exported=null,configured=false,pending=null,revision=0;
function status(s){$('status').textContent=s}
function clearPreview(){revision++;pending=null;$('silhouette').checked=false;$('silhouette').disabled=true;$('combine').disabled=true;$('combinedresults').replaceChildren();$('maskresults').replaceChildren()}
function invalidate(){clearPreview();exported=null;$("runmask").disabled=true;$("maskresults").replaceChildren();if(url){URL.revokeObjectURL(url);url=null}$('download').replaceChildren();$('json').hidden=true;$('reviewed').checked=false;$('export').disabled=true}
function active(){return state&&state.objects[selected]}
function refresh(){const options=$('objects');options.replaceChildren();if(!state)return;state.objects.forEach((o,i)=>{let e=document.createElement('option');e.value=i;e.textContent=(i+1)+'. '+o.name;options.append(e)});options.value=selected;$('name').value=active().name;$('geometry').textContent=state.image_size.join(' x ')+' source pixels. Selected box: '+(active().box?active().box.join(', '):'not drawn')+'. Points: '+active().points.length;draw();$('export').disabled=!$('reviewed').checked||!state.objects.every(o=>o.box&&o.name.trim())}
function draw(){ctx.clearRect(0,0,c.width,c.height);if(!img)return;ctx.drawImage(img,0,0);const scale=c.width/Math.max(1,c.getBoundingClientRect().width);ctx.lineWidth=scale*2;ctx.font=scale*16+'px sans-serif';state.objects.forEach((o,i)=>{ctx.strokeStyle=i===selected?'#0756b8':'#777';ctx.fillStyle='#0756b8';if(o.box){let b=o.box;ctx.strokeRect(b[0],b[1],b[2]-b[0],b[3]-b[1]);ctx.fillText(String(i+1),b[0]+4,b[1]+scale*20)}o.points.forEach((p,j)=>{ctx.beginPath();ctx.fillStyle=o.labels[j]?'#008535':'#d91830';ctx.arc(p[0],p[1],scale*4,0,Math.PI*2);ctx.fill()})});if(drag){ctx.strokeStyle='#0756b8';ctx.strokeRect(drag[0],drag[1],drag[2]-drag[0],drag[3]-drag[1])}}
function coord(e){const b=c.getBoundingClientRect();return [Math.min(c.width-1,Math.max(0,(e.clientX-b.left)*c.width/b.width)),Math.min(c.height-1,Math.max(0,(e.clientY-b.top)*c.height/b.height))].map(Math.round)}
function snapshot(){history.push(JSON.stringify({objects:state.objects,selected}));invalidate()}
function reset(){generation++;state=null;img=null;drag=null;pan=null;history=[];$('zoom').value='100';c.style.width='100%';$('mode').value='box';$('modehint').textContent='Box: drag around the whole object.';invalidate();for(let id of ['objects','name','add','remove','undo','mode','reviewed'])$(id).disabled=true;c.width=600;c.height=300;draw();$('objects').replaceChildren();$('name').value='';$('geometry').textContent='No source loaded.'}
$('mode').onchange=()=>{drag=null;pan=null;$('modehint').textContent={pan:'Pan: drag to move a zoomed image.',box:'Box: drag around the whole object.',positive:'Positive point: click on product.',negative:'Negative point: click inside an empty hole or background.'}[$('mode').value];draw()};
$('zoom').onchange=()=>{c.style.width=$('zoom').value+'%';draw()};
$('source').onchange=()=>{reset();status('Source changed. Load it before drawing.')};
$('prepare').onclick=async()=>{const file=$('source').files[0];if(!file){status('Choose an image first.');return}reset();const token=generation;status('Preparing source preview...');let f=new FormData();f.append('photo',file);try{const res=await fetch('/prompt-prepare',{method:'POST',body:f});if(!res.ok)throw new Error(await res.text());const data=await res.json();if(token!==generation)return;job=data.job;const preview=new Image();preview.onload=()=>{if(token!==generation)return;img=preview;state={source_sha256:data.source_sha256,image_size:data.image_size,origin:'reviewed_source_geometry',objects:[{name:'product',points:[],labels:[]}]};selected=0;c.width=data.image_size[0];c.height=data.image_size[1];for(let id of ['objects','name','add','remove','undo','mode','reviewed'])$(id).disabled=false;refresh();status('Source loaded. Draw a box. SHA256 '+data.source_sha256)};preview.onerror=()=>status('Preview could not load; do not export.');preview.src=data.preview_url}catch(e){if(token===generation)status(String(e.message))}};
$('objects').onchange=()=>{selected=Number($('objects').value);drag=null;refresh()};$('name').oninput=()=>{if(!state)return;active().name=$('name').value;invalidate();refresh()};
$('add').onclick=()=>{if(!state||state.objects.length>=8){status('Maximum 8 objects.');return}snapshot();state.objects.push({name:'object '+(state.objects.length+1),points:[],labels:[]});selected=state.objects.length-1;refresh()};
$('remove').onclick=()=>{if(!state||state.objects.length===1){status('Keep at least one selected object.');return}snapshot();state.objects.splice(selected,1);selected=Math.min(selected,state.objects.length-1);refresh()};
$('undo').onclick=()=>{if(!history.length)return;const old=JSON.parse(history.pop());state.objects=old.objects;selected=old.selected;invalidate();refresh()};
c.onpointerdown=e=>{if(!state)return;e.preventDefault();let p=coord(e);c.setPointerCapture(e.pointerId);if($('mode').value==='pan'){pan=[e.clientX,e.clientY,$('viewport').scrollLeft,$('viewport').scrollTop];return}if($('mode').value==='box'){drag=[...p,...p];draw()}else{if(active().points.length>=32){status('Maximum 32 points per object.');return}snapshot();active().points.push(p);active().labels.push($('mode').value==='positive'?1:0);refresh()}};
c.onpointermove=e=>{if(pan){$('viewport').scrollLeft=pan[2]+pan[0]-e.clientX;$('viewport').scrollTop=pan[3]+pan[1]-e.clientY;return}if(drag){const p=coord(e);drag[2]=p[0];drag[3]=p[1];draw()}};
c.onpointerup=e=>{if(pan){pan=null;return}if(!drag)return;let p=coord(e),b=[Math.min(drag[0],p[0]),Math.min(drag[1],p[1]),Math.max(drag[0],p[0]),Math.max(drag[1],p[1])];drag=null;if(b[2]-b[0]<2||b[3]-b[1]<2){status('Box too small; drag around the whole object.');draw();return}snapshot();active().box=b;refresh()};c.onpointercancel=()=>{drag=null;pan=null;draw()};
window.addEventListener('resize',draw);
$('reviewed').onchange=refresh;
$('export').onclick=()=>{if(!state||!$('reviewed').checked)return;const names=state.objects.map(o=>o.name.trim());if(!state.objects.every(o=>o.box)||names.some(n=>!n)||new Set(names).size!==names.length){status('Draw every box and use unique object names.');return}let data=structuredClone(state);data.objects.forEach(o=>o.name=o.name.trim());exported=data;$("runmask").disabled=!configured||!$("automatic").files[0];const text=JSON.stringify(data,null,2);if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='reviewed-prompts.json';a.className='download';a.textContent='Download reviewed-prompts.json';$('download').replaceChildren(a);$('json').textContent=text;$('json').hidden=false;status('Prompts exported for this exact source. No model has run. Inspect resulting masks after the CLI run.')};

fetch('/reviewed-status').then(r=>r.json()).then(d=>{configured=d.configured;$('runconfig').textContent=configured?'Pinned checkpoint configured on this local server.':'Disabled: start this server with --reviewed-checkpoint PATH_TO_EXISTING_sam_hq_vit_tiny.pth in the optional HQ-SAM environment. No download is performed.';}).catch(()=>{$('runconfig').textContent='Server setup could not be checked.'});

function renderPreviews(root,d){root.replaceChildren();if(d.download_url){const a=document.createElement('a');a.href=d.download_url;a.textContent='Download reviewed-mask result ZIP';a.className='download';root.append(a)}for(const color of ['white','black','magenta']){const p=document.createElement('p');p.textContent=color+' review';const im=document.createElement('img');im.src=d.preview_urls[color];im.alt=color+' background mask review';im.style.width='100%';im.style.maxWidth='700px';root.append(p,im)}}
$('automatic').onchange=()=>{clearPreview();$('runmask').disabled=!configured||!exported||!$('automatic').files[0]};
$('silhouette').onchange=()=>{$('combine').disabled=!pending||!$('silhouette').checked};
$('runmask').onclick=async()=>{if(!exported||!configured)return;if(exported.objects.some(o=>!o.labels.includes(1))){$('runstatus').textContent='Add at least one positive point on each product, inspect prompts and export again. A box alone is not enough.';return}clearPreview();const token=revision;const f=new FormData();f.append('job',job);f.append('prompts',JSON.stringify(exported));f.append('automatic',$('automatic').files[0]);$('runmask').disabled=true;$('runstatus').textContent='Inferring HQ-SAM silhouette on CPU only. No intersection yet. Up to180seconds.';try{const res=await fetch('/reviewed-run',{method:'POST',body:f});if(!res.ok)throw new Error(await res.text());const d=await res.json();if(token!==revision)return;renderPreviews($('maskresults'),d);await Promise.all([...$('maskresults').querySelectorAll('img')].map(im=>new Promise((resolve,reject)=>{if(im.complete)return im.naturalWidth?resolve():reject(Error('preview image failed'));im.onload=resolve;im.onerror=()=>reject(Error('preview image failed'))})));if(token!==revision)return;pending=d;$('silhouette').disabled=false;$('runstatus').textContent='Silhouette ready, NOT combined. Inspect every preview. Reject holes or unwanted background by editing prompts and retrying. Only accept a correct silhouette.';}catch(e){if(token===revision){clearPreview();$('runstatus').textContent='Preview failed: '+e.message}}finally{$('runmask').disabled=!configured||!exported||!$('automatic').files[0]}};
$('combine').onclick=async()=>{if(!pending||!$('silhouette').checked)return;const token=revision;const f=new FormData();f.append('job',pending.job);f.append('fingerprint',pending.fingerprint);f.append('acceptance','I inspected this exact inferred silhouette');$('combine').disabled=true;$('silhouette').disabled=true;$('runstatus').textContent='Combining the explicitly reviewed silhouette with automatic alpha.';try{const res=await fetch('/reviewed-confirm',{method:'POST',body:f});if(!res.ok)throw new Error(await res.text());const d=await res.json();if(token!==revision)return;pending=null;renderPreviews($('combinedresults'),d);$('runstatus').textContent='Combined after explicit silhouette review. NOT quality-accepted. Inspect final edges, missing parts, glass and source completeness. Intersection cannot restore lost parts.';}catch(e){if(token===revision){clearPreview();$('runstatus').textContent='Combination failed: '+e.message}}};
</script></body></html>'''
